def u(t: Tensor, x: Tensor, y: Tensor, z: Tensor) -> Tensor:
	E_x = 100.0000000*torch.exp(-1.25*(2.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)**2)*((1.000000000*y**5+(2.000000000*x**2+2.000000000*z**2+(t+1.500000000)**2)*y**3+(-2.000000000*t-3.000000000)*z*x*y**2+(1.000000000*x**4+(2.000000000*z**2+(t+1.500000000)**2)*x**2+1.000000000*z**4+(t+1.500000000)**2*z**2)*y+(-2.000000000*t-3.000000000)*z*x**3+((-2.000000000*t-3.000000000)*z**3+(-.4500000000-.3000000000*t)*z)*x)*(x**2+y**2+z**2)**(1/2)+(-2.000000000*t-3.000000000)*y**5+1.000000000*x*y**4*z+((-6.000000000-4.000000000*t)*x**2+(-6.000000000-4.000000000*t)*z**2-.1000000000*t-.1500000000)*y**3+(2.000000000*x**3*z+(2.000000000*z**3+(2.450000000+1.000000000*t**2+3.000000000*t)*z)*x)*y**2+((-2.000000000*t-3.000000000)*x**4+((-6.000000000-4.000000000*t)*z**2-.1000000000*t-.1500000000)*x**2+(-2.000000000*t-3.000000000)*z**4+(-.1000000000*t-.1500000000)*z**2)*y+1.000000000*x**5*z+(2.000000000*z**3+(2.450000000+1.000000000*t**2+3.000000000*t)*z)*x**3+(1.000000000*z**5+(2.450000000+1.000000000*t**2+3.000000000*t)*z**3+.3000000000e-1*z)*x)/(x**2+y**2+z**2)**(5/2)
	E_y =  -100.0000000*((1.000000000*x**5+(2.000000000*y**2+2.000000000*z**2+(t+1.500000000)**2)*x**3+(2.000000000*t+3.000000000)*z*y*x**2+(1.000000000*y**4+(2.000000000*z**2+(t+1.500000000)**2)*y**2+1.000000000*z**4+(t+1.500000000)**2*z**2)*x+(2.000000000*t+3.000000000)*z*y**3+((2.000000000*t+3.000000000)*z**3+(.4500000000+.3000000000*t)*z)*y)*(x**2+y**2+z**2)**(1/2)+(-2.000000000*t-3.000000000)*x**5-1.000000000*x**4*y*z+((-6.000000000-4.000000000*t)*y**2+(-6.000000000-4.000000000*t)*z**2-.1000000000*t-.1500000000)*x**3+(-2.000000000*y**3*z+(-2.000000000*z**3+(-2.450000000-1.000000000*t**2-3.000000000*t)*z)*y)*x**2+((-2.000000000*t-3.000000000)*y**4+((-6.000000000-4.000000000*t)*z**2-.1000000000*t-.1500000000)*y**2+(-2.000000000*t-3.000000000)*z**4+(-.1000000000*t-.1500000000)*z**2)*x-1.000000000*y**5*z+(-2.000000000*z**3+(-2.450000000-1.000000000*t**2-3.000000000*t)*z)*y**3+(-1.000000000*z**5+(-2.450000000-1.000000000*t**2-3.000000000*t)*z**3-.3000000000e-1*z)*y)*torch.exp(-1.25*(2.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)**2)/(x**2+y**2+z**2)**(5/2)
	E_z =  -100.0000000*(((-2.000000000*t-3.000000000)*x**4+((-6.000000000-4.000000000*t)*y**2+(-2.000000000*t-3.000000000)*z**2-.1000000000*t-.1500000000)*x**2+(-2.000000000*t-3.000000000)*y**4+((-2.000000000*t-3.000000000)*z**2-.1000000000*t-.1500000000)*y**2+(.2000000000*t+.3000000000)*z**2)*(x**2+y**2+z**2)**(1/2)+1.000000000*x**6+(3.000000000*y**2+2.000000000*z**2+(t+1.500000000)**2)*x**4+(3.000000000*y**4+(4.000000000*z**2+2.000000000*(t+1.500000000)**2)*y**2+.1000000000e-1+1.000000000*z**4+(t+1.947213595)*(t+1.052786405)*z**2)*x**2+1.000000000*y**6+(2.000000000*z**2+(t+1.500000000)**2)*y**4+(.1000000000e-1+1.000000000*z**4+(t+1.947213595)*(t+1.052786405)*z**2)*y**2-.2000000000e-1*z**2-.2000000000*z**4)*torch.exp(-1.25*(2.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)**2)/(x**2+y**2+z**2)**(5/2)
	B_x =  100.0000000*((-1.000000000*y**5+(-2.000000000*x**2-2.000000000*z**2-(t+1.500000000)**2)*y**3+(-2.000000000*t-3.000000000)*z*x*y**2+(-1.000000000*x**4+(-2.000000000*z**2-(t+1.500000000)**2)*x**2-1.000000000*z**4-(t+1.500000000)**2*z**2)*y+(-2.000000000*t-3.000000000)*z*x**3+((-2.000000000*t-3.000000000)*z**3+(-.4500000000-.3000000000*t)*z)*x)*(x**2+y**2+z**2)**(1/2)+(2.000000000*t+3.000000000)*y**5+1.000000000*x*y**4*z+((6.000000000+4.000000000*t)*x**2+(6.000000000+4.000000000*t)*z**2+.1000000000*t+.1500000000)*y**3+(2.000000000*x**3*z+(2.000000000*z**3+(2.450000000+1.000000000*t**2+3.000000000*t)*z)*x)*y**2+((2.000000000*t+3.000000000)*x**4+((6.000000000+4.000000000*t)*z**2+.1000000000*t+.1500000000)*x**2+(2.000000000*t+3.000000000)*z**4+(.1000000000*t+.1500000000)*z**2)*y+1.000000000*x**5*z+(2.000000000*z**3+(2.450000000+1.000000000*t**2+3.000000000*t)*z)*x**3+(1.000000000*z**5+(2.450000000+1.000000000*t**2+3.000000000*t)*z**3+.3000000000e-1*z)*x)*torch.exp(-1.25*(2.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)**2)/(x**2+y**2+z**2)**(5/2)
	B_y =  100.0000000*((1.000000000*x**5+(2.000000000*y**2+2.000000000*z**2+(t+1.500000000)**2)*x**3+(-2.000000000*t-3.000000000)*z*y*x**2+(1.000000000*y**4+(2.000000000*z**2+(t+1.500000000)**2)*y**2+1.000000000*z**4+(t+1.500000000)**2*z**2)*x+(-2.000000000*t-3.000000000)*z*y**3+((-2.000000000*t-3.000000000)*z**3+(-.4500000000-.3000000000*t)*z)*y)*(x**2+y**2+z**2)**(1/2)+(-2.000000000*t-3.000000000)*x**5+1.000000000*x**4*y*z+((-6.000000000-4.000000000*t)*y**2+(-6.000000000-4.000000000*t)*z**2-.1000000000*t-.1500000000)*x**3+(2.000000000*y**3*z+(2.000000000*z**3+(2.450000000+1.000000000*t**2+3.000000000*t)*z)*y)*x**2+((-2.000000000*t-3.000000000)*y**4+((-6.000000000-4.000000000*t)*z**2-.1000000000*t-.1500000000)*y**2+(-2.000000000*t-3.000000000)*z**4+(-.1000000000*t-.1500000000)*z**2)*x+1.000000000*y**5*z+(2.000000000*z**3+(2.450000000+1.000000000*t**2+3.000000000*t)*z)*y**3+(1.000000000*z**5+(2.450000000+1.000000000*t**2+3.000000000*t)*z**3+.3000000000e-1*z)*y)*torch.exp(-1.25*(2.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)**2)/(x**2+y**2+z**2)**(5/2)
	B_z =  -100.0000000*(((-2.000000000*t-3.000000000)*x**4+((-6.000000000-4.000000000*t)*y**2+(-2.000000000*t-3.000000000)*z**2-.1000000000*t-.1500000000)*x**2+(-2.000000000*t-3.000000000)*y**4+((-2.000000000*t-3.000000000)*z**2-.1000000000*t-.1500000000)*y**2+(.2000000000*t+.3000000000)*z**2)*(x**2+y**2+z**2)**(1/2)+1.000000000*x**6+(3.000000000*y**2+2.000000000*z**2+(t+1.500000000)**2)*x**4+(3.000000000*y**4+(4.000000000*z**2+2.000000000*(t+1.500000000)**2)*y**2+.1000000000e-1+1.000000000*z**4+(t+1.947213595)*(t+1.052786405)*z**2)*x**2+1.000000000*y**6+(2.000000000*z**2+(t+1.500000000)**2)*y**4+(.1000000000e-1+1.000000000*z**4+(t+1.947213595)*(t+1.052786405)*z**2)*y**2-.2000000000e-1*z**2-.2000000000*z**4)*torch.exp(-1.25*(2.*(x**2+y**2+z**2)**(1/2)-2.*t-3.)**2)/(x**2+y**2+z**2)**(5/2)

	return torch.vstack((E_x, E_y, E_z, B_x, B_y, B_z))